/**
 * File: simplyCountdown.js
 * Kode library yang sudah dirapikan, dibersihkan dari error minifikasi,
 * dan siap langsung digunakan.
 */
(function (window) {
  "use strict";

  // Helper untuk penggabungan opsi/setting
  var extendOptions = function (out) {
    out = out || {};
    for (var i = 1; i < arguments.length; i++) {
      var obj = arguments[i];
      if (!obj) continue;
      for (var key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key)) {
          if (typeof obj[key] === "object" && !Array.isArray(obj[key])) {
            out[key] = extendOptions(out[key] || {}, obj[key]);
          } else {
            out[key] = obj[key];
          }
        }
      }
    }
    return out;
  };

  // Helper untuk membuat elemen HTML struktur angka & teks
  var createSection = function (container, params, sectionClass) {
    var section = document.createElement("div");
    var amountSpan = document.createElement("span");
    var wordSpan = document.createElement("span");
    var innerDiv = document.createElement("div");

    innerDiv.appendChild(amountSpan);
    innerDiv.appendChild(wordSpan);
    section.appendChild(innerDiv);

    section.classList.add(params.sectionClass, sectionClass);
    amountSpan.classList.add(params.amountClass);
    wordSpan.classList.add(params.wordClass);

    container.appendChild(section);

    return {
      full: section,
      amount: amountSpan,
      word: wordSpan
    };
  };

  // Fungsi Utama Library
  window.simplyCountdown = function (element, options) {
    var defaultOptions = {
      year: 2027,
      month: 12,
      day: 31,
      hours: 0,
      minutes: 0,
      seconds: 0,
      words: {
        days: { singular: "day", plural: "days" },
        hours: { singular: "hour", plural: "hours" },
        minutes: { singular: "minute", plural: "minutes" },
        seconds: { singular: "second", plural: "seconds" }
      },
      plural: true,
      inline: false,
      enableUtc: false,
      onEnd: function () {},
      refresh: 1000,
      inlineClass: "simply-countdown-inline",
      sectionClass: "simply-section",
      amountClass: "simply-amount",
      wordClass: "simply-word",
      zeroPad: false,
      countUp: false
    };

    var settings = extendOptions({}, defaultOptions, options);
    var targetElements;

    if (typeof element === "string") {
      targetElements = document.querySelectorAll(element);
    } else {
      targetElements = element;
    }

    var targetDate = new Date(
      settings.year,
      settings.month - 1,
      settings.day,
      settings.hours,
      settings.minutes,
      settings.seconds
    );

    var finalTargetDate = settings.enableUtc
      ? new Date(
          targetDate.getUTCFullYear(),
          targetDate.getUTCMonth(),
          targetDate.getUTCDate(),
          targetDate.getUTCHours(),
          targetDate.getUTCMinutes(),
          targetDate.getUTCSeconds()
        )
      : targetDate;

    var initCountdown = function (targetEl) {
      var intervalId;
      var sections;

      if (settings.inline) {
        var inlineSpan = document.createElement("span");
        inlineSpan.classList.add(settings.inlineClass);
        targetEl.appendChild(inlineSpan);
        sections = inlineSpan;
      } else {
        sections = {
          days: createSection(targetEl, settings, "simply-days-section"),
          hours: createSection(targetEl, settings, "simply-hours-section"),
          minutes: createSection(targetEl, settings, "simply-minutes-section"),
          seconds: createSection(targetEl, settings, "simply-seconds-section")
        };
      }

      var update = function () {
        var now = new Date();
        var secondsLeft;

        if (settings.enableUtc) {
          var nowUtc = new Date(
            now.getFullYear(),
            now.getMonth(),
            now.getDate(),
            now.getHours(),
            now.getMinutes(),
            now.getSeconds()
          ).getTime();
          secondsLeft = (finalTargetDate.getTime() - nowUtc) / 1000;
        } else {
          secondsLeft = (finalTargetDate.getTime() - now.getTime()) / 1000;
        }

        var days = 0, hours = 0, minutes = 0, seconds = 0;

        if (secondsLeft > 0) {
          days = Math.floor(secondsLeft / 86400);
          secondsLeft %= 86400;
          hours = Math.floor(secondsLeft / 3600);
          secondsLeft %= 3600;
          minutes = Math.floor(secondsLeft / 60);
          seconds = Math.floor(secondsLeft % 60);
        } else if (settings.countUp) {
          secondsLeft = (now.getTime() - finalTargetDate.getTime()) / 1000;
          days = Math.floor(secondsLeft / 86400);
          secondsLeft %= 86400;
          hours = Math.floor(secondsLeft / 3600);
          secondsLeft %= 3600;
          minutes = Math.floor(secondsLeft / 60);
          seconds = Math.floor(secondsLeft % 60);
        } else {
          days = 0;
          hours = 0;
          minutes = 0;
          seconds = 0;
          window.clearInterval(intervalId);
          settings.onEnd();
        }

        var dayWord = settings.plural && days > 1 ? settings.words.days.plural : settings.words.days.singular;
        var hourWord = settings.plural && hours > 1 ? settings.words.hours.plural : settings.words.hours.singular;
        var minuteWord = settings.plural && minutes > 1 ? settings.words.minutes.plural : settings.words.minutes.singular;
        var secondWord = settings.plural && seconds > 1 ? settings.words.seconds.plural : settings.words.seconds.singular;

        if (settings.inline) {
          targetEl.innerHTML =
            days + " " + dayWord + ", " +
            hours + " " + hourWord + ", " +
            minutes + " " + minuteWord + ", " +
            seconds + " " + secondWord + ".";
        } else {
          sections.days.amount.textContent = (settings.zeroPad && days < 10 ? "0" : "") + days;
          sections.days.word.textContent = dayWord;
          sections.hours.amount.textContent = (settings.zeroPad && hours < 10 ? "0" : "") + hours;
          sections.hours.word.textContent = hourWord;
          sections.minutes.amount.textContent = (settings.zeroPad && minutes < 10 ? "0" : "") + minutes;
          sections.minutes.word.textContent = minuteWord;
          sections.seconds.amount.textContent = (settings.zeroPad && seconds < 10 ? "0" : "") + seconds;
          sections.seconds.word.textContent = secondWord;
        }
      };

      update();
      intervalId = window.setInterval(update, settings.refresh);
    };

    if (targetElements && targetElements.length !== undefined && !(targetElements instanceof HTMLElement)) {
      Array.prototype.forEach.call(targetElements, function (el) {
        initCountdown(el);
      });
    } else if (targetElements) {
      initCountdown(targetElements);
    }
  };

  if (window.jQuery) {
    window.jQuery.fn.simplyCountdown = function (options) {
      window.simplyCountdown(this.selector, options);
    };
  }
})(window);